script:
// Háromfázisú rendszer – csillag (Y) vagy delta (Δ) terhelés
// Three-phase system – star (Y) or delta (Δ) load
//   u_k = √2·U_f·sin(ωt − k·120°)      U_v = √3·U_f      Ī = Ū / Z,   Z = R + jX
//   Y: Ī_N = Ī₁ + Ī₂ + Ī₃           Δ: Ī₁ = Ī₁₂ − Ī₃₁ (vonali áram / line current)

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Háromfázisú rendszer", en: "Three-phase system"});
timeScale(0.002);   // 50 Hz → 0,1 Hz a képernyőn (10 s / periódus) / 50 Hz shown at 0.1 Hz (10 s per cycle)
plotWindow(0.06);   // 3 periódus 50 Hz-en / 3 periods at 50 Hz

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("U",  {hu: "Vonali feszültség U_v", en: "Line voltage U_L"}, 100, 690, 400, 1, "V");
param("f",  {hu: "Frekvencia f", en: "Frequency f"}, 10, 100, 50, 1, "Hz");
param("R1", {hu: "Ellenállás R₁", en: "Resistance R₁"}, 1, 200, 40, 1, "Ω");
param("R2", {hu: "Ellenállás R₂", en: "Resistance R₂"}, 1, 200, 40, 1, "Ω");
param("R3", {hu: "Ellenállás R₃", en: "Resistance R₃"}, 1, 200, 40, 1, "Ω");
param("X",  {hu: "Reaktancia X (50 Hz-en; + induktív, − kapacitív)", en: "Reactance X (at 50 Hz; + inductive, − capacitive)"}, -100, 100, 30, 1, "Ω");
// Legördülő lista: [érték, felirat] párok / Drop-down list: [value, label] pairs
choice("conn", {hu: "Kapcsolás", en: "Connection"},
  [["Y", {hu: "Csillag, nullavezetővel", en: "Star, with neutral"}], ["D", {hu: "Delta (háromszög)", en: "Delta"}]], "Y");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("rot",  {hu: "Forgó fázorok", en: "Rotating phasors"}, true);
toggle("line", {hu: "Vonali feszültségek", en: "Line voltages"}, false);
// Ezek változásakor a jelenet újraindul / The scene restarts when these change
resetOn("conn");

const PH = [C.L1, C.L2, C.L3];   // IEC: barna, fekete, szürke / brown, black, grey
const IX = ["₁", "₂", "₃"];

function solve() {
  const Xf = P.X >= 0 ? P.X * P.f / 50 : P.X * 50 / P.f;         // X_L ∝ f,  X_C ∝ 1/f
  const Z = [complex(P.R1, Xf), complex(P.R2, Xf), complex(P.R3, Xf)];
  const Uf = P.U / sqrt(3);
  const Up = [0, 1, 2].map(k => cpolar(Uf, -k * deg(120)));        // fázisfeszültségek / phase voltages
  const Ul = [0, 1, 2].map(k => Up[k].sub(Up[(k + 1) % 3]));       // Ū₁₂, Ū₂₃, Ū₃₁
  let Ub, Ib, IL, IN = complex(0, 0);   // Ub, Ib: a fogyasztón / across the load;  IL: vonali áram / line current
  if (P.conn === "Y") {
    Ub = Up; Ib = Up.map((u, k) => u.div(Z[k])); IL = Ib;
    IN = IL[0].add(IL[1]).add(IL[2]);
  } else {
    Ub = Ul; Ib = Ul.map((u, k) => u.div(Z[k]));
    IL = [0, 1, 2].map(k => Ib[k].sub(Ib[(k + 2) % 3]));
  }
  let S = complex(0, 0);                                                 // S = P + jQ
  for (let k = 0; k < 3; k++) S = S.add(Ub[k].mul(Ib[k].conj()));
  return {Uf, Up, Ul, Ub, Ib, IL, IN, S, Z};
}
const inst = (z, th) => sqrt(2) * z.abs() * sin(th + z.arg());     // pillanatérték / instantaneous value

let th = 0;   // ωt, folytonos frekvenciaváltáskor is / stays continuous when f changes
// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => { th += 2 * PI * P.f * dt; });

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const s = solve();
  const rot = P.rot ? th : 0;

  // ── Fázorábra / phasor diagram ──
  const ox = 250, oy = 335;
  line(ox - 215, oy, ox + 215, oy, {stroke: C.light, lw: 1});
  line(ox, oy - 215, ox, oy + 215, {stroke: C.light, lw: 1});
  // Lépték: feszültség px/V, áram külön px/A / scale: voltage px per V, current its own px per A
  const ku = 185 / (P.line ? P.U : s.Uf);
  const Imax = max(...s.IL.map(z => z.abs()), s.IN.abs(), 1e-9);
  const ki = 125 / Imax;   // az áram külön léptékű / currents use their own scale
  for (let k = 0; k < 3; k++) {
    if (P.line) {
      const a = s.Up[(k + 1) % 3], z = s.Ul[k];
      const sx = ox + a.abs() * ku * cos(a.arg() + rot), sy = oy - a.abs() * ku * sin(a.arg() + rot);
      phasor(sx, sy, z.abs() * ku, z.arg() + rot, {stroke: C.purple, lw: 1.8}, "U" + IX[k] + IX[(k + 1) % 3]);
    }
    phasor(ox, oy, s.Up[k].abs() * ku, s.Up[k].arg() + rot, {stroke: PH[k], lw: 3}, "U" + IX[k]);
    phasor(ox, oy, s.IL[k].abs() * ki, s.IL[k].arg() + rot, {stroke: PH[k], lw: 2, dash: [7, 4]}, "I" + IX[k]);
  }
  if (P.conn === "Y" && s.IN.abs() > Imax * 0.02) phasor(ox, oy, s.IN.abs() * ki, s.IN.arg() + rot, {stroke: C.blue, lw: 2.5}, "Iɴ");
  circle(ox, oy, 4, {fill: C.ink});
  text({hu: "— feszültség    - - áram (saját lépték)", en: "— voltage    - - current (own scale)"}, 40, 580, {size: 12, color: C.gray});

  // ── Kapcsolási rajz / circuit ──
  const yL = [150, 195, 240], yN = 285, x0 = 545;
  // Pillanatnyi vonali áramok a nyilakhoz / instantaneous line currents for the arrows
  const iL = s.IL.map(z => inst(z, th)), iN = inst(s.IN, th), ipk = sqrt(2) * Imax;
  for (let k = 0; k < 3; k++) text("L" + (k + 1), x0 - 8, yL[k] + 5, {size: 14, bold: true, color: PH[k], align: "right"});
  if (P.conn === "Y") {
    const xs = [700, 800, 900];
    for (let k = 0; k < 3; k++) {
      polyline([[x0, yL[k]], [xs[k], yL[k]], [xs[k], 330]], {stroke: PH[k], lw: 2.5});
      box(xs[k], 370, 34, 80, 0, {fill: "#ffffff", stroke: PH[k], lw: 2});
      text("Z" + IX[k], xs[k] + 24, 376, {size: 14});
      polyline([[xs[k], 410], [xs[k], 460], [800, 460]], {stroke: PH[k], lw: 2});
    }
    text("N", x0 - 8, yN + 5, {size: 14, bold: true, color: C.blue, align: "right"});
    polyline([[x0, yN], [610, yN], [610, 520], [800, 520], [800, 460]], {stroke: C.blue, lw: 2});
    circle(800, 460, 5, {fill: C.ink});
    const LN = 50 * iN / ipk;
    if (abs(LN) > 4) arrow(575 + LN / 2, yN - 11, 575 - LN / 2, yN - 11, {stroke: C.blue, lw: 2.5, id: "nullavezető áram (nyíl)"});
  } else {
    const A = [800, 335], B = [655, 505], Cc = [945, 505];
    polyline([[x0, yL[0]], [800, yL[0]], A], {stroke: PH[0], lw: 2.5});
    polyline([[x0, yL[1]], [655, yL[1]], B], {stroke: PH[1], lw: 2.5});
    polyline([[x0, yL[2]], [945, yL[2]], Cc], {stroke: PH[2], lw: 2.5});
    const edges = [[A, B], [B, Cc], [Cc, A]];   // Z₁: L1–L2,  Z₂: L2–L3,  Z₃: L3–L1
    edges.forEach(([p1, p2], k) => {
      line(p1[0], p1[1], p2[0], p2[1], {stroke: C.ink, lw: 2});
      const mx = (p1[0] + p2[0]) / 2, my = (p1[1] + p2[1]) / 2, a = atan2(p2[1] - p1[1], p2[0] - p1[0]);
      box(mx, my, 60, 26, a, {fill: "#ffffff", stroke: C.ink, lw: 2});
      const nx = mx - 800, ny = my - 448, nl = hypot(nx, ny);
      text("Z" + IX[k], mx + nx / nl * 34, my + ny / nl * 34 + 5, {size: 14, align: "center"});
    });
    for (const q of [A, B, Cc]) circle(q[0], q[1], 5, {fill: C.ink});
  }
  for (let k = 0; k < 3; k++) {              // vonali áramok pillanatnyi iránya / instantaneous line currents
    const Lk = 50 * iL[k] / ipk;
    if (abs(Lk) > 4) arrow(610 - Lk / 2, yL[k] - 11, 610 + Lk / 2, yL[k] - 11, {stroke: C.red, lw: 2.5, id: "vonali áram (nyíl)"});
  }
  text({hu: "piros nyíl: pillanatnyi áramirány", en: "red arrows: instantaneous current"}, x0, 110, {size: 12, color: C.gray});

  // ── Mért értékek / readouts ──
  show({hu: "Fázisfeszültség U_f = U_v/√3", en: "Phase voltage U_ph = U_L/√3"}, s.Uf, "V");
  for (let k = 0; k < 3; k++) show({hu: "Vonali áram I" + IX[k], en: "Line current I" + IX[k]}, s.IL[k].abs(), "A");
  if (P.conn === "Y") show({hu: "Nullavezető árama Iɴ", en: "Neutral current Iɴ"}, s.IN.abs(), "A");
  else show({hu: "Fázisáram I₁₂ (a fogyasztón)", en: "Phase current I₁₂ (in the load)"}, s.Ib[0].abs(), "A");
  show({hu: "Fáziseltolás φ = arc tg X/R₁", en: "Phase angle φ = atan X/R₁"}, todeg(s.Z[0].arg()), "°");
  show({hu: "Hatásos teljesítmény P", en: "Active power P"}, s.S.re, "W");
  show({hu: "Meddő teljesítmény Q", en: "Reactive power Q"}, s.S.im, "var");
  show({hu: "Látszólagos teljesítmény S", en: "Apparent power S"}, s.S.abs(), "VA");
  show({hu: "Teljesítménytényező cos φ", en: "Power factor cos φ"}, s.S.re / max(s.S.abs(), 1e-9), "");

  for (let k = 0; k < 3; k++) plot("u" + IX[k], inst(s.Up[k], th), {unit: "V", color: PH[k], group: "u"});
  for (let k = 0; k < 3; k++) plot("i" + IX[k], iL[k], {unit: "A", color: PH[k], group: "i"});
  if (P.conn === "Y") plot("iɴ", iN, {unit: "A", color: C.blue, group: "i"});
});
